import{z as d,x as B,o as s,c as p,q as t,j as E,D as r,d as i,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"回收 shrinker","description":"","frontmatter":{"title":"回收 shrinker","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-reclaim.md","filePath":"cs/memory-reclaim.md","lastUpdated":1791063341000}'),m={name:"cs/memory-reclaim.md"};function h(c,a,A,k,C,D){const n=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=t('<h1 id="回收-shrinker" tabindex="-1">回收 shrinker <a class="header-anchor" href="#回收-shrinker" aria-label="Permalink to &quot;回收 shrinker&quot;">​</a></h1><div class="epigraph"><p>空闲页不够时，内核主动收缩页 Cache、slab 与匿名驻留，而不是等到下一次缺页才 CLOCK 一页。</p><footer>—— 据 Denning 的负荷控制；Bovet、Love 对 kswapd 与 shrinker 的整理</footer></div><p><a href="/cs/slab-allocator">上一课</a>会囤页。<a href="/cs/anon-vs-file-page">文件页</a> 与匿名页都占帧。<a href="/cs/thrashing">抖动</a> 已说要减负荷。缺口是后台<strong>回收</strong>：水位（watermark）、kswapd、以及可注册的 shrinker，把可丢的页还给 buddy，供缺页与大页使用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯反应式置换：每次缺页才选牺牲，延迟打在用户指令上。内核分配（网络、VFS）失败更糟。缺口：维护低/高水位；低于低水位唤醒守护线程，扫描 LRU/CLOCK、写回脏文件页、换出匿名、调用各子系统 shrinker（dentry、inode、slab）。直接回收（direct reclaim）发生在分配路径上，可能阻塞。本课不把每条 LRU 链表名字背完。</p><p><span class="marginnote">术语翻译：水位（watermark）就是把「空闲页还剩多少」画成 min / low / high 三条刻度线，像水箱警报——降到 low 开泵（唤醒 kswapd 后台补水），跌破 min 等不及了，正在分配的那段代码只能自己当场抽水（直接回收）。</span></p><p><span class="marginnote">shrinker 是回调：VFS 缓存「我可以丢多少 dentry」。回收器按压力要它们交页。与 GC 不同：这里回收的是帧，对象语义由各 cache 自己保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配失败或周期性：计算需要多少页。优先丢干净文件页（再读文件）；再写回；再换出匿名；再收缩 slab。达到高水位停止。压缩（compaction）把已用页挪到一边，拼出 buddy 高阶块给大页。OOM 仅当这些都不够。与过度提交对照：回收增加「现在能拿出的帧」，不减少已承诺的 VMA。</p><p><span class="marginnote">数字实例：假设 kswapd 要回收 64 MiB、页大小 4 KiB，就是凑 64 × 1024 ÷ 4 = 16384 页。若扫到的多是干净文件页，直接从链表摘掉即可，连盘都不用碰——这正是回收优先丢干净文件页的原因；脏页则要先写回再丢，多一次磁盘写。</span></p>',10)),(s(),E(o,null,{default:r(()=>[l(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E4%BD%8E%E4%BA%8E%E6%B0%B4%E4%BD%8D%22%5D%20--%3E%20KSW%5B%22kswapd%20%2F%20%E7%9B%B4%E6%8E%A5%E5%9B%9E%E6%94%B6%22%5D%0A%20%20KSW%20--%3E%20FILE%5B%22%E4%B8%A2%E6%88%96%E5%86%99%E5%9B%9E%E6%96%87%E4%BB%B6%E9%A1%B5%22%5D%0A%20%20KSW%20--%3E%20ANON%5B%22%E6%8D%A2%E5%87%BA%E5%8C%BF%E5%90%8D%22%5D%0A%20%20KSW%20--%3E%20SH%5B%22shrinker%20%E4%BA%A4%20cache%22%5D%0A%20%20SH%20--%3E%20BUD%5B%22%E9%A1%B5%E5%9B%9E%20buddy%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"回收把 CLOCK、工作集、文件/匿名分类收成一条控制环：目标是 buddy 的低阶与高阶都有货。它解释了为何机器「内存看起来满」仍流畅——满的是 Cache，不是不可丢的匿名。文件系统课即将把「文件」当成正题；本课只要求 Cache 可收缩。不要把回收写成数据库查询计划。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：看到「内存占用 95%」就以为该清内存。实际上满的常是 page cache——这些页随时可丢、要用再读回，占着反而加速文件访问；真正危险的是不可丢的匿名页把空闲页压到水位以下，逼出换出甚至 OOM。")],-1)),(s(),E(o,null,{default:r(()=>[l(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E7%A9%BA%E9%97%B2%E9%A1%B5%E7%BC%93%E6%85%A2%E6%B6%88%E8%80%97%22%5D%20--%3E%7C%22%E8%B7%8C%E7%A0%B4%20low%22%7C%20WAKE%5B%22%E5%94%A4%E9%86%92%20kswapd%22%5D%0A%20%20WAKE%20--%3E%20LOOP%5B%22%E5%90%8E%E5%8F%B0%E5%9B%9E%E6%94%B6%22%5D%0A%20%20LOOP%20--%3E%7C%22%E8%A1%A5%E5%88%B0%20high%22%7C%20SLEEP%5B%22kswapd%20%E4%BC%91%E7%9C%A0%22%5D%0A%20%20DROP%20--%3E%7C%22%E8%B7%8C%E7%A0%B4%20min%22%7C%20DIRECT%5B%22%E5%88%86%E9%85%8D%E8%B7%AF%E5%BE%84%E7%9B%B4%E6%8E%A5%E5%9B%9E%E6%94%B6%22%5D%0A%20%20DIRECT%20--%3E%7C%22%E4%B8%80%E6%97%A0%E6%89%80%E8%8E%B7%22%7C%20OOM%5B%22%E8%A7%A6%E5%8F%91%20OOM%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PSI（压力停滞信息）的全部用户接口。不保证实时任务不被直接回收卡住——实时路径应预留或 memlock。下一课离开虚存单元：用户如何用路径与描述符看字节，而不是看帧。</p><p>后课默认：帧可以从 Cache 挤回。文件作为用户看见的字节流，下一课从零命名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>水位驱动 kswapd 与 shrinker，主动还页给 buddy。</li><li>先可丢文件页，再匿名换出；OOM 仍是最后手段。</li><li>文件字节流抽象是下一单元的第一课。</li><li>出处：Denning；Bovet and Cesati, <em>ULK</em>；Love, <em>LKD</em>。</li></ul>',5))])}const b=d(m,[["render",h]]);export{f as __pageData,b as default};
